def compute(vars):
    total_employees = vars["v2"]
    union_represented = vars["v1"]

    if total_employees == 0:
        return None

    value = union_represented / total_employees
    return {
        "value": value,
        "trace": {
            "union_represented": union_represented,
            "total_employees": total_employees,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
